using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Xml.Linq;using System.Collections.Generic;
namespace V15Voice {
public static class VietnamesePack {
 public static string Folder {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"V15VoiceStudio","vietnamese_pack");}}
 public static string Home(){var x=StateFiles.Read(Path.Combine(Folder,"active.xml"));if(x==null||StateFiles.S(x,"sdk")!="3.8.3")throw new Exception("Chưa cài gói tiếng Việt. Mở Công cụ & thiết lập → GÓI TIẾNG VIỆT → Cài gói.");string name=StateFiles.S(x,"folder");if(String.IsNullOrEmpty(name)||name!=Path.GetFileName(name)||name.Contains("..")||name.IndexOfAny(new[]{'/', '\\', ':'})>=0)throw new Exception("Đường dẫn gói tiếng Việt không hợp lệ.");string home=Path.Combine(Folder,name);if(!File.Exists(Path.Combine(home,"ready.json")))throw new Exception("Gói tiếng Việt chưa cài hoàn tất. Cài lại gói trong Công cụ & thiết lập.");return home;}
 public static string Python(){if(Environment.OSVersion.Platform!=PlatformID.Win32NT)return Environment.GetEnvironmentVariable("V15_VI_PYTHON")??"python3";return Path.Combine(Home(),"runtime","python.exe");}
 public static string Script(string root,string name){return Path.Combine(root,"source","vi",name);}
 public static void Check(KokoroEngine e){if(e.ModelFolder!="vieneu_v3")throw new Exception("Bộ giọng Việt không hợp lệ.");Home();foreach(string p in new[]{Python(),Script(e.Root,"vi_worker.py"),Tempo.Executable(e.Root)})if(Environment.OSVersion.Platform==PlatformID.Win32NT&&!File.Exists(p))throw new Exception("Thiếu tệp tiếng Việt: "+p);if(!String.IsNullOrEmpty(e.ReferencePath)&&!File.Exists(e.ReferencePath))throw new Exception("Không tìm thấy mẫu giọng Việt đã lưu.");}
 public static void KillTree(Process p){try{if(p.HasExited)return;if(Environment.OSVersion.Platform==PlatformID.Win32NT){using(var k=Process.Start(new ProcessStartInfo("taskkill.exe","/PID "+p.Id+" /T /F"){UseShellExecute=false,CreateNoWindow=true})){k.WaitForExit(5000);}}else p.Kill();}catch{}try{if(!p.HasExited)p.Kill();}catch{}}
 public static string Install(string root,string mode,KokoroEngine owner,Action<string> notify){
  string bootstrap=ExternalSpeech.Python(root);if(Environment.OSVersion.Platform==PlatformID.Win32NT&&!File.Exists(bootstrap))throw new Exception("Thiếu Python của gói AI hiện tại. Cài đủ gói AI trước khi thêm tiếng Việt.");
  var start=new ProcessStartInfo(bootstrap,KokoroEngine.Q(Script(root,"setup_vi.py"))+" --folder "+KokoroEngine.Q(Folder)+" --mode "+mode+" --ffmpeg "+KokoroEngine.Q(Tempo.Executable(root))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};start.EnvironmentVariables["PYTHONIOENCODING"]="utf-8";string error="",result="",lastStatus="Đang cài gói tiếng Việt";var timer=Stopwatch.StartNew();long pulse=0;string logDir=Path.Combine(Folder,"logs");Directory.CreateDirectory(logDir);string log=Path.Combine(logDir,"install-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".log");
  using(var p=new Process{StartInfo=start}){p.OutputDataReceived+=(s,e)=>{if(e.Data==null)return;try{if(e.Data.StartsWith("V15_STATUS\t")){lastStatus=ExternalSpeech.Decode(e.Data.Substring(11));notify(lastStatus);}if(e.Data.StartsWith("V15_SETUP_OK\t"))result=ExternalSpeech.Decode(e.Data.Substring(13));}catch{}};p.ErrorDataReceived+=(s,e)=>{if(e.Data!=null){lock(p){try{File.AppendAllText(log,e.Data+"\n",Encoding.UTF8);}catch{}if(e.Data.StartsWith("V15_STATUS\t")){try{lastStatus=ExternalSpeech.Decode(e.Data.Substring(11));notify(lastStatus);}catch{}}error+=e.Data+"\n";if(error.Length>7000)error=error.Substring(error.Length-7000);}}};p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();try{while(!p.WaitForExit(150)){if(timer.ElapsedMilliseconds-pulse>=5000){pulse=timer.ElapsedMilliseconds;notify(lastStatus+" · "+timer.Elapsed.TotalMinutes.ToString("0.0")+" phút · có thể Dừng tác vụ");}if(owner.Cancelled){KillTree(p);throw new OperationCanceledException();}}p.WaitForExit();if(owner.Cancelled)throw new OperationCanceledException();if(p.ExitCode!=0||String.IsNullOrEmpty(result))throw new Exception("Cài gói tiếng Việt chưa hoàn tất. Bộ tiếng Anh và gói Việt đang dùng vẫn được giữ.\r\nNhật ký: "+log+"\r\n"+error);return result;}finally{if(!p.HasExited)KillTree(p);}}
 }
}
public partial class MainForm {
 ComboBox languagePicker=new ComboBox();Label viPackStatus=new Label();bool languageChanging;
 bool VietnameseSelected{get{return family.SelectedIndex==(int)EngineKind.VieNeu;}}
 void BuildLanguagePicker(FlowLayoutPanel panel){AddLabel(panel,"Ngôn ngữ lời đọc · dùng chung hàng đợi",false);languagePicker.Width=250;languagePicker.DropDownStyle=ComboBoxStyle.DropDownList;languagePicker.Items.AddRange(new object[]{"English · US","Tiếng Việt"});languagePicker.SelectedIndex=0;panel.Controls.Add(languagePicker);extraControls.Add(languagePicker);languagePicker.SelectedIndexChanged+=(s,e)=>{if(languageChanging)return;family.SelectedIndex=languagePicker.SelectedIndex==1?(int)EngineKind.VieNeu:0;};}
 void SyncLanguage(){languageChanging=true;try{languagePicker.SelectedIndex=VietnameseSelected?1:0;if(grid.Columns.Count>3)grid.Columns[3].HeaderText=VietnameseSelected?"Lời đọc tiếng Việt":"Lời đọc English";}finally{languageChanging=false;}}
 void BuildVietnameseTools(FlowLayoutPanel panel){AddLabel(panel,"GÓI TIẾNG VIỆT · OFFLINE",true);AddLabel(panel,"Bản 2.0: lưu model không cần quyền symlink. Cài riêng một lần, có mạng khi tải. Đọc SRT/TXT, giọng có sẵn và sao chép giọng Việt. GPU dùng CUDA 12.8 riêng; không thay gói tiếng Anh.",false);panel.Controls.Add(Btn("Cài gói Việt · NVIDIA GPU",async(s,e)=>await InstallVietnamese("gpu")));panel.Controls.Add(Btn("Cài gói Việt · CPU",async(s,e)=>await InstallVietnamese("cpu")));panel.Controls.Add(Btn("Kiểm tra gói Việt / thử giọng",async(s,e)=>await TestVietnamese()));viPackStatus.AutoSize=true;viPackStatus.MaximumSize=new System.Drawing.Size(320,0);panel.Controls.Add(viPackStatus);RefreshVietnameseStatus();AddLabel(panel,"★ Việt: lựa chọn ưu tiên của tác giả VieNeu; phong cách là gợi ý. MP4/MP3 → SRT và SRT căn từng từ hiện vẫn dành cho tiếng Anh.",false);}
 void RefreshVietnameseStatus(){try{viPackStatus.Text="Đã cài: "+Path.GetFileName(VietnamesePack.Home())+" · chọn Tiếng Việt ở tab Tạo voice.";}catch{viPackStatus.Text="Chưa cài gói tiếng Việt. Chọn nút cài GPU hoặc CPU ở trên.";}}
 async Task InstallVietnamese(string mode){if(busy)return;try{active=new KokoroEngine{Root=root};var owner=active;SetBusy(true);status.Text="Đang cài gói tiếng Việt. Có thể Dừng tác vụ; lần cài sau dùng lại phần tải đệm.";string result=await Task.Run(()=>VietnamesePack.Install(root,mode,owner,ShowActivity));viPackStatus.Text=result;status.Text="Đã cài và tự kiểm tra gói tiếng Việt. Chọn Tiếng Việt để tạo WAV.";}catch(OperationCanceledException){status.Text="Đã dừng cài tiếng Việt. Gói đang dùng được giữ nguyên.";}catch(Exception e){Error(e);}finally{if(active!=null)active.Dispose();active=null;SetBusy(false);RefreshVietnameseStatus();}}
 async Task TestVietnamese(){if(busy)return;string folder=Path.Combine(Path.GetTempPath(),"V15_vi_test_"+Guid.NewGuid().ToString("N"));try{var p=catalog.All.FirstOrDefault(v=>v.Kind==EngineKind.VieNeu&&String.IsNullOrEmpty(v.ReferencePath));if(p==null)throw new Exception("Thiếu danh sách giọng Việt.");active=EngineFor(p);active.CheckFiles();SetBusy(true);Directory.CreateDirectory(folder);var engine=active;string output=Path.Combine(folder,"test.wav");var w=await Task.Run(()=>engine.Generate("Xin chào bạn. Đây là giọng tiếng Việt được tạo hoàn toàn trên máy tính.",1,output));if(player!=null)player.Stop();if(clonePreviewPath!=null)try{File.Delete(clonePreviewPath);}catch{}clonePreviewPath=Path.Combine(stateDir,"vi_test.wav");File.Copy(output,clonePreviewPath,true);Play(clonePreviewPath);viPackStatus.Text="Thử thành công · "+engine.DeviceInfo+" · "+w.Duration.ToString("0.00")+" giây.";}catch(OperationCanceledException){status.Text="Đã dừng thử tiếng Việt.";}catch(Exception e){Error(e);}finally{if(active!=null)active.Dispose();active=null;SetBusy(false);try{Directory.Delete(folder,true);}catch{}}}
}
}
